from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import BoolInput, CodeInput, DataInput, DropdownInput, StrInput, IntInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.editor_views import task_view, rows as task_rows
from sic_workflow.editor_response_reader import read_original_response,response_read_view
from sic_workflow.v2_client import CoreClient
from sic_workflow.workbench_support import cached, context_of, error_rows, object_value, perform, reset, table, text


class SICEditorTask(Component):
    display_name = 'SIC Editor任务与只读档案'
    description = '程序冻结编辑范围；一次执行可按宿主预算进行有界反馈。全部原始交付保持只读，未成为可改目标。'
    icon = 'ClipboardList'
    name = 'SICEditorTask'
    inputs = [DataInput(name='previous', display_name='前一步', required=False),
              StrInput(name='chain_id', display_name='工作路线', value=''),
              DropdownInput(name='action', display_name='任务动作', options=['查看冻结任务', '读取一位Editor原响应', '准备单Editor', '准备双Editor分工', '执行一位Editor单轮', '并发执行所有Editor'], value='查看冻结任务', real_time_refresh=True),
              StrInput(name='source_id', display_name='待处理WB', value=''),
              StrInput(name='job_id', display_name='已冻结任务', value=''),
              StrInput(name='editor', display_name='Editor身份', value='editor-1'),
              StrInput(name='response_call_id', display_name='原响应调用ID（空为最新；可选历史反馈轮）', value=''),
              IntInput(name='response_offset',display_name='原响应页字符起点',value=0),
              IntInput(name='response_limit',display_name='原响应页字符预算（1..8192）',value=2048),
              StrInput(name='editor_one_name', display_name='第一Editor身份（与editor:alpha选择对应）', value='editor-1'),
              StrInput(name='editor_two_name', display_name='第二Editor身份', value='editor-2'),
              StrInput(name='editor_one_units', display_name='Editor 1单元（逗号分隔）', value='u1'),
              StrInput(name='editor_two_units', display_name='Editor 2单元（逗号分隔）', value='u2'),
              DataInput(name='archive_page', display_name='导航器已选档案页（只读）', required=False),
              BoolInput(name='include_archive_page', display_name='准备时预取并冻结已选页', value=False),
              CodeInput(name='readonly_reads', display_name='其他只读页定位数组（高级）', value='[]', advanced=True),
              BoolInput(name='allow_write', display_name='允许冻结/执行此任务', value=False),
              BoolInput(name='allow_model', display_name='允许已选Editor及配置内反馈调用', value=False)]
    outputs = [Output(name='result', display_name='真实任务与范围', method='run_task', group_outputs=True),
               Output(name='scope', display_name='可改单元 / 已冻结分工', method='scope', group_outputs=True),
               Output(name='layout', display_name='冻结计划 / 实际请求 / fallback（只读）', method='layout', group_outputs=True),
               Output(name='aliases', display_name='局部别名 → canonical范围（只读）', method='aliases', group_outputs=True),
               Output(name='background', display_name='只读CB / I / 档案 / 原始响应', method='background', group_outputs=True)]

    outputs += [Output(name='deliveries',display_name='实际尝试 / 被拒交付 / 未返回（非候选）',method='delivery_attempts',group_outputs=True),
                Output(name='original_response',display_name='绑定原响应页（只读，不修复）',method='original_response_page',group_outputs=True)]

    def _pre_run_setup(self):
        reset(self)

    def update_build_config(self, build_config, field_value, field_name=None):
        if field_name == 'action':
            preparing = field_value.startswith('准备')
            for key in ('source_id', 'archive_page', 'include_archive_page', 'readonly_reads'):
                build_config[key]['show'] = preparing
            for key in ('editor_one_units', 'editor_two_units', 'editor_one_name', 'editor_two_name'):
                build_config[key]['show'] = field_value == '准备双Editor分工'
            build_config['editor']['show'] = field_value in {'执行一位Editor单轮','读取一位Editor原响应'}
            for key in ('response_call_id','response_offset','response_limit'):build_config[key]['show']=field_value=='读取一位Editor原响应'
            build_config['allow_model']['show'] = field_value in {'执行一位Editor单轮', '并发执行所有Editor'}
        return build_config

    def _act(self):
        context = context_of(self)
        job = self.job_id or context.get('job_id')
        if self.action=='读取一位Editor原响应':
            if self.response_offset<0 or not 1<=self.response_limit<=8192:raise ValueError('原响应页必须offset>=0且limit 1..8192')
            result=read_original_response(CoreClient(),context,job,self.editor,self.response_offset,self.response_limit,getattr(self,'response_call_id','') or None)
        elif self.action.startswith('准备'):
            reads = object_value(self.readonly_reads, list)
            if self.include_archive_page:
                page = self.archive_page.data if self.archive_page else {}
                if not page.get('ok') or page.get('operation') != 'memory.page':
                    raise ValueError('Connect a successful immutable memory.page result first')
                body = page['result']
                reads.append({key: body[key] for key in ('kind', 'object_id', 'offset', 'limit')})
            payload = {'source_id': self.source_id or context.get('source_id'), 'readonly_reads': reads}
            if self.action == '准备双Editor分工':
                payload['assignments'] = [{'editor': name, 'unit_ids': [item.strip() for item in units.split(',') if item.strip()]}
                                          for name, units in ((self.editor_one_name,self.editor_one_units),(self.editor_two_name,self.editor_two_units))]
            result = perform(self, 'edit.prepare', payload, context=context)
        elif self.action == '执行一位Editor单轮':
            result = perform(self, 'edit.run', {'job_id': job, 'editor': self.editor}, context=context)
        elif self.action == '并发执行所有Editor':
            result = perform(self, 'edit.run_all', {'job_id': job}, context=context)
        else:
            result = perform(self, 'chain.get', context=context)
        if result.get('ok'):
            snapshot = perform(self, 'chain.get', context=result['context'])
            job = result['context'].get('job_id', job)
            raw_job = snapshot.get('result', {}).get('jobs', {}).get(job, {})
            result['task_view'] = task_view(raw_job) if raw_job else {}
            if isinstance(result.get('result',{}).get('job'),dict):result['result']['job']=result['task_view']
            if result.get('operation')=='chain.get':result['result']={'job_id':job,'job':result['task_view'],'selection_readonly':True}
            if 'base_cut' in result['task_view']:
                result['context']['reviewed_cut'] = result['task_view']['base_cut']
            if self.action.startswith('准备') and reads and not result['task_view'].get('readonly_reads'):
                return {'ok': False, 'context': result['context'], 'operation': 'edit.prepare',
                        'error': {'code': 'archive_prefetch_unavailable', 'message': 'Core created the task but did not freeze the requested archive pages. Do not run this job; reload the supported core or explicitly prepare another task.'},
                        'evidence': {'task_created': True, 'model_called': False}}
        return result

    def run_task(self) -> Data:
        return Data(data=cached(self, self._act))

    def scope(self) -> DataFrame:
        value = cached(self, self._act)
        if not value.get('ok'):
            return table(error_rows(value))
        job = value.get('task_view', {})
        assignments = {uid: assignment['editor'] for assignment in job.get('assignments', []) for uid in assignment['unit_ids']}
        return table([{'单元': unit['unit_id'], '可改正文': unit['text'], '冻结Editor': assignments.get(unit['unit_id'], 'KEEP'),
                       '来源锚（只读）': text(unit.get('anchor', {})), '状态': job.get('status')}
                      for unit in job.get('source_snapshot', {}).get('units', [])])

    def background(self) -> DataFrame:
        value = cached(self, self._act)
        if not value.get('ok'):
            return table(error_rows(value))
        job = value.get('task_view', {})
        rows = [{'来源': '固定CB有限投影', '只读材料': text(job.get('background', [])), '未读与导航': text(job.get('background_manifest', {}))},
                {'来源': '覆写时I快照', '只读材料': text(job.get('instant_reference', {}))},
                {'来源': '程序预取冻结档案页', '只读材料': text(job.get('readonly_reads', []))}]
        rows.extend({'来源': ('canonical转换结果（原模型响应单独引用） / ' if response.get('canonical_response_id') else '原始单轮交付 / ') + editor, '只读材料': text(response)} for editor, response in job.get('responses', {}).items())
        for editor, background in job.get('editor_backgrounds', {}).items():
            rows.append({'来源':'该Editor实际冻结背景 / '+editor, '只读材料':text(background),
                         '当前任务所属':text({'context_id':job.get('context_id'),'level':job.get('level'),'wb_id':job.get('wb_id'),'base_cut':job.get('base_cut')})})
        for editor, instant in job.get('editor_instants', {}).items():
            rows.append({'来源':'该Editor实际冻结I / '+editor,'只读材料':text(instant)})
        return table(rows)

    def layout(self) -> DataFrame:
        value=cached(self,self._act)
        return table(task_rows(value.get('task_view',{}))['prefix_rows']) if value.get('ok') else table(error_rows(value))

    def aliases(self) -> DataFrame:
        value=cached(self,self._act)
        return table(task_rows(value.get('task_view',{}))['alias_rows']) if value.get('ok') else table(error_rows(value))

    def delivery_attempts(self) -> DataFrame:
        value=cached(self,self._act)
        return table(task_rows(value.get('task_view',{}))['attempt_rows']) if value.get('ok') else table(error_rows(value))

    def original_response_page(self) -> Data:
        return Data(data=response_read_view(cached(self,self._act)))

import copy

from sic_workflow.workbench_component import WorkbenchComponent as Component
from lfx.io import BoolInput, CodeInput, DataInput, DropdownInput, IntInput, MultilineInput, StrInput, Output
from lfx.schema import Data, DataFrame
from sic_workflow.workbench_support import cached, context_of, error_rows, object_value, perform, reset, table, text


class SICCandidate(Component):
    display_name = "SIC 候选版本编辑"
    description = "修订尚未发布的op与P/V/I，保留模型原始交付；旧校验随版本失效。已发布CB与op不可改。R13–25/R61。"
    icon = "FilePenLine"
    name = "SICCandidate"
    inputs = [
        DataInput(name="previous", display_name="前一步", required=False),
        StrInput(name="chain_id", display_name="工作路线", value=""),
        StrInput(name="job_id", display_name="编辑任务", value=""),
        DropdownInput(name="action", display_name="候选操作", options=["读取候选", "追加操作", "修改一项操作", "修订操作与 P/V/I", "移除一项操作", "修改 P/V/I", "替换完整序列（高级）", "校验候选", "发布此版本"], value="读取候选", real_time_refresh=True),
        IntInput(name="expected_revision", display_name="已核对候选版本（-1沿用前一步）", value=0),
        IntInput(name="operation_number", display_name="修改/移除第几项（从1起）", value=1),
        DropdownInput(name="op", display_name="内容操作", options=["KEEP", "DELETE", "FLAG", "REORDER", "COMPRESS", "REPLACE", "ADD"], value="REPLACE"),
        StrInput(name="target", display_name="原文单元ID", value=""),
        MultilineInput(name="content", display_name="新正文或标记", value=""),
        MultilineInput(name="reason", display_name="编辑理由 / 信息损失说明", value=""),
        IntInput(name="order", display_name="重排位置", value=0),
        StrInput(name="anchor_target", display_name="ADD插入锚（可选）", value=""),
        DropdownInput(name="anchor_position", display_name="ADD锚位置", options=["before", "after"], value="after"),
        DropdownInput(name="lifecycle", display_name="生成内容的生命周期", options=["P", "V", "I"], value="P", info="操作账本本身始终持久；KEEP/DELETE/REORDER仅P。"),
        StrInput(name="view_key", display_name="I视图名称", value=""),
        DropdownInput(name="risk", display_name="信息损失风险", options=["none", "low", "medium", "high", "unknown"], value="unknown"),
        MultilineInput(name="persistent_text", display_name="P：本次固定内容", value="", info="空值表示此版本P为空；正文可含换行。"),
        MultilineInput(name="volatile_text", display_name="V：下一WB材料", value=""),
        CodeInput(name="instant_views", display_name="I：当前独立视图（JSON对象）", value="{}", info="不属于可编辑WB；下一覆写换版。决策四视角另有专门工作台。"),
        CodeInput(name="full_ops", display_name="完整候选op数组（高级）", value="[]", advanced=True),
        IntInput(name="expected_cut", display_name="已核对cut（-1沿用任务/前一步快照）", value=0),
        BoolInput(name="allow_write", display_name="允许本次修订/发布", value=False),
    ]
    outputs = [Output(name="result", display_name="候选 / 校验 / 发布结果", method="run_candidate", group_outputs=True),
               Output(name="operations", display_name="有序op与来源", method="operations", group_outputs=True),
               Output(name="originals", display_name="原始Editor交付（只读）", method="originals", group_outputs=True),
               Output(name="lifecycles", display_name="P / V / I去向", method="lifecycles", group_outputs=True)]
    for _field in inputs:
        if _field.name in {"operation_number", "op", "target", "content", "reason", "order", "anchor_target", "anchor_position", "lifecycle", "view_key", "risk", "persistent_text", "volatile_text", "instant_views", "full_ops", "expected_cut"}:
            _field.show = False

    def _pre_run_setup(self):
        reset(self)
        self._candidate_original = None

    def update_build_config(self, build_config, field_value, field_name=None):
        if field_name != "action":
            return build_config
        typed = field_value in {"追加操作", "修改一项操作", "修订操作与 P/V/I"}
        for key in ("op", "target", "content", "reason", "order", "anchor_target", "anchor_position", "lifecycle", "view_key", "risk"):
            build_config[key]["show"] = typed
        build_config["operation_number"]["show"] = field_value in {"修改一项操作", "修订操作与 P/V/I", "移除一项操作"}
        for key in ("persistent_text", "volatile_text", "instant_views"):
            build_config[key]["show"] = field_value in {"修改 P/V/I", "修订操作与 P/V/I"}
        build_config["full_ops"]["show"] = field_value == "替换完整序列（高级）"
        build_config["expected_cut"]["show"] = field_value == "发布此版本"
        return build_config

    def _act(self):
        context = context_of(self)
        job = self.job_id or context.get("job_id")
        if not job:
            return {"ok": False, "context": context, "error": {"code": "job_required", "message": "先选择已交付的编辑任务；不能以新空任务代替候选修订。"}}
        context["job_id"] = job
        original = perform(self, "edit.candidate.get", {"job_id": job}, context=context)
        if original.get("ok"):
            self._candidate_original = original["result"]
        if not original.get("ok") or self.action == "读取候选":
            return original
        candidate = original["result"]
        # Rust v2 returns the mutable candidate under result.candidate while
        # the job identity/revision sit beside it. Normalize that envelope for
        # the editable body without losing the outer revision.
        if isinstance(candidate.get("candidate"), dict):
            candidate = {**candidate, **candidate["candidate"]}
        expected_revision = context.get("candidate_revision") if self.expected_revision == -1 else self.expected_revision
        if candidate["revision"] != expected_revision:
            return {"ok": False, "context": context, "error": {"code": "candidate_stale", "message": f"候选已是版本{candidate['revision']}，请重新读取；不自动覆盖。"}}
        if self.action == "校验候选":
            return perform(self, "edit.validate", {"job_id": job}, context=context)
        if self.action == "发布此版本":
            expected_cut = context.get('reviewed_cut') if self.expected_cut == -1 else self.expected_cut
            if expected_cut is None:
                return {'ok': False, 'context': context, 'error': {'code': 'cut_snapshot_required', 'message': 'Prepare/read the job or explicitly supply its reviewed cut; no blind latest-version overwrite.'}}
            return perform(self, "cut.publish", {"job_id": job, "expected_cut": expected_cut,
                           "expected_candidate_revision": expected_revision,
                           "idempotency_key": f"{job}:candidate:{expected_revision}"}, context=context)
        ops, pvi = copy.deepcopy(candidate["ops"]), copy.deepcopy(candidate.get("pvi", {}))
        if self.action == "修改 P/V/I":
            pvi = {"P": [self.persistent_text] if self.persistent_text else [],
                   "V": [self.volatile_text] if self.volatile_text else [], "I": object_value(self.instant_views)}
        elif self.action == "替换完整序列（高级）":
            ops = object_value(self.full_ops, list)
        elif self.action == "移除一项操作":
            if not 1 <= self.operation_number <= len(ops):
                raise ValueError("操作编号超出当前候选范围")
            ops.pop(self.operation_number - 1)
        else:
            op = {"op": self.op}
            op["lifecycle"] = self.lifecycle
            op["risk"] = self.risk
            if self.lifecycle == "I":
                op["view_key"] = self.view_key
            if self.op != "ADD":
                op["target"] = self.target
            if self.op in {"FLAG", "COMPRESS", "REPLACE", "ADD"}:
                op["content"] = self.content
            if self.reason:
                op["reason"] = self.reason
            if self.op == "REORDER":
                op["order"] = self.order
            if self.op == "ADD" and self.anchor_target:
                op["anchor"] = {"target": self.anchor_target, "position": self.anchor_position}
            if self.action == "追加操作":
                ops.append(op)
            else:
                if not 1 <= self.operation_number <= len(ops):
                    raise ValueError("操作编号超出当前候选范围")
                ops[self.operation_number - 1] = op
            if self.action == "修订操作与 P/V/I":
                pvi = {"P": [self.persistent_text] if self.persistent_text else [],
                       "V": [self.volatile_text] if self.volatile_text else [], "I": object_value(self.instant_views)}
        result = perform(self, "edit.candidate.update", {"job_id": job, "expected_revision": expected_revision,
                         "ops": ops, "pvi": pvi}, context=context)
        if result.get("ok"):
            result["presentation"] = {"submitted_ops": ops, "submitted_pvi": pvi,
                                      "original_responses_read_only": True, "old_validation_stale": True}
        return result

    def run_candidate(self) -> Data:
        return Data(data=cached(self, self._act))

    def operations(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        ops = result.get("ops", result.get("material", {}).get("ops", envelope.get("presentation", {}).get("submitted_ops", [])))
        return table([{"序号": i + 1, "记录下标": i, "操作": op.get("op"), "目标": text(op.get("target", op.get("targets", ""))),
                       "内容": op.get("content", ""), "内容生命周期": op.get("lifecycle", "P"), "风险": op.get("risk", "unknown"),
                       "理由": op.get("reason", ""), "来源": op.get("origin", op.get("editor", "候选提案")),
                       "候选版本": result.get("revision", self.expected_revision)} for i, op in enumerate(ops)])

    def lifecycles(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        result = envelope["result"]
        pvi = result.get("pvi", envelope.get("presentation", {}).get("submitted_pvi", {}))
        material = result.get("material", {})
        if material:
            pvi = {"P": [material.get("body", "")], "V": material.get("volatile", []), "I": material.get("instant", {})}
        return table([{"生命周期": key, "去向": destination, "内容": text(pvi.get(key, {} if key == "I" else [])),
                       "旧CB可改": False} for key, destination in [("P", "本次CB固定"), ("V", "下一WB可再编辑"), ("I", "独立当前视图，不进入WB")]])

    def originals(self) -> DataFrame:
        envelope = cached(self, self._act)
        if not envelope.get("ok"):
            return table(error_rows(envelope))
        original = getattr(self, "_candidate_original", None) or {}
        responses = original.get("original_responses", {})
        entries = responses.items() if isinstance(responses, dict) else enumerate(responses)
        return table([{"交付者": str(key), "原始交付（只读）": text(value), "人工修订是否冒充原始输出": False}
                      for key, value in entries])
